function showToast(t,e="success"){const n=document.getElementById("toast-container"),s=document.createElement("div");s.className=`toast ${e}`,s.innerHTML=`<p style="color: var(--color-brand-primary); font-weight: 500;">${t}</p>`,n.appendChild(s),setTimeout(()=>{s.style.animation="slideInRight 0.3s ease reverse forwards",setTimeout(()=>s.remove(),300)},3500)}function renderTrips(){const t=document.getElementById("trips-tbody"),e=document.getElementById("loading"),n=document.getElementById("empty-state");if(e.style.display="none",0===trips.length)return t.innerHTML="",void(n.style.display="block");n.style.display="none",t.innerHTML=trips.map(t=>`\n      <tr>\n        <td><span class="badge-pill ${"available"===t.status?"badge-success":"esgotado"}">${"available"===t.status?"Disponível":"Esgotado"}</span></td>\n        <td style="font-weight: 600;">${t.title}</td>\n        <td style="color: var(--color-text-secondary);">${t.date}</td>\n        <td>\n          <button class="btn btn-outline" style="padding: 0.4rem 0.8rem; font-size: 0.85rem; margin-right: 0.5rem;" onclick="editTrip('${t.id}')">Editar</button>\n          <button class="btn btn-outline" style="padding: 0.4rem 0.8rem; font-size: 0.85rem; color: #EF4444; border-color: #FCA5A5;" onclick="deleteTrip('${t.id}')">Excluir</button>\n        </td>\n      </tr>\n    `).join("")}async function saveTrip(t){t.preventDefault();try{showToast("Viagem salva com sucesso!","success"),closeModal(),renderTrips()}catch(t){showToast("Erro ao salvar viagem. Tente novamente.","error")}}